"""Ilustrações da Loja Ticker, recortadas da imagem de referência enviada pelo Gabriel: moedas, baú e a moeda T (coloridas) e os ícones
(máscaras: só o formato, pintado pelo CSS com a cor do estado). Cada item: (WebP em base64, largura, altura). Módulo só de dados."""
from __future__ import annotations

IMAGENS = {
    "moedas": ("", 383, 219),
    "bau": ("", 360, 226),
    "tc": ("", 70, 70),
    "m_estrela": ("", 96, 96),
    "m_loja": ("", 96, 92),
    "m_extrato": ("", 96, 92),
    "m_cart": ("", 96, 84),
    "m_gift": ("", 96, 89),
    "m_relogio": ("", 93, 96),
    "m_presente": ("", 96, 93),
}


def uri(nome: str) -> str:
    d = IMAGENS.get(nome)
    return f"data:image/webp;base64,{d[0]}" if d else ""


def proporcao(nome: str) -> float:
    d = IMAGENS.get(nome)
    return d[1] / d[2] if d else 1.0


def existe(nome: str) -> bool:
    return nome in IMAGENS
